import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

export const dynamic = 'force-dynamic'

/**
 * Railway health check endpoint.
 *
 * Called by Railway on every deploy before marking the service healthy.
 * Must respond in < 1 second.
 *
 * Returns 200 when all checks pass, 503 when any check fails.
 */
export async function GET() {
  const checks: Record<string, string> = {
    web: 'ok',
    db: 'unknown',
  }

  try {
    const supabase = await createClient()
    const { error } = await supabase.from('_health').select('id').limit(1).maybeSingle()
    checks['db'] = error ? 'fail' : 'ok'
  } catch (err) {
    logger.warn({ err }, 'health check db ping failed')
    checks['db'] = 'fail'
  }

  const allOk = Object.values(checks).every((v) => v === 'ok')

  return Response.json(
    {
      status: allOk ? 'healthy' : 'degraded',
      checks,
      timestamp: new Date().toISOString(),
      version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
    },
    { status: allOk ? 200 : 503 }
  )
}
import { timingSafeEqual, createHmac } from 'node:crypto'
import { type NextRequest, NextResponse } from 'next/server'
import { z } from 'zod'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

export const dynamic = 'force-dynamic'

/**
 * Dodo Payments webhook handler.
 *
 * Security:
 * 1. HMAC-SHA256 signature verified with timingSafeEqual before any processing
 * 2. Zod schema validation before any DB write
 * 3. Idempotency via webhook_events table (duplicate event_id = 200 no-op)
 *
 * The subscriptions table is ONLY written by this webhook — never by the app.
 */

const DodoEventSchema = z.object({
  webhookId: z.string(),
  eventType: z.enum([
    'subscription.active',
    'subscription.cancelled',
    'subscription.paused',
    'subscription.renewed',
    'payment.succeeded',
    'payment.failed',
    'payment.refunded',
  ]),
  timestamp: z.string(),
  data: z.record(z.unknown()),
})

type DodoEvent = z.infer<typeof DodoEventSchema>

async function verifySignature(
  rawBody: string,
  signature: string | null,
  secret: string
): Promise<boolean> {
  if (!signature) return false

  try {
    const hmac = createHmac('sha256', secret).update(rawBody).digest('hex')
    const expected = Buffer.from(hmac, 'utf-8')
    const received = Buffer.from(signature, 'utf-8')

    if (expected.length !== received.length) return false
    return timingSafeEqual(expected, received)
  } catch {
    return false
  }
}

async function handleSubscriptionActive(event: DodoEvent, supabase: ReturnType<typeof createServiceRoleClient>) {
  const data = event.data as {
    subscriptionId?: string
    customerId?: string
    metadata?: { studioId?: string }
    status?: string
    nextBillingDate?: string
    planId?: string
  }

  const studioId = data.metadata?.studioId
  if (!studioId) {
    logger.warn({ eventId: event.webhookId }, 'dodo webhook: missing studioId in metadata')
    return
  }

  // Determine plan tier from planId (mapped via env vars)
  const planTier = resolvePlanTier(data.planId ?? '')

  const { error } = await supabase.from('subscriptions').upsert(
    {
      studio_id: studioId,
      dodo_subscription_id: data.subscriptionId ?? null,
      dodo_customer_id: data.customerId ?? null,
      plan_tier: planTier,
      status: 'active',
      current_period_end: data.nextBillingDate ?? null,
      updated_at: new Date().toISOString(),
    },
    { onConflict: 'studio_id' }
  )

  if (error) {
    logger.error({ err: error, studioId }, 'dodo webhook: failed to upsert subscription')
    throw error
  }

  await logAuditAction(null, 'subscription.activated', { type: 'studio', id: studioId }, {
    planTier,
    subscriptionId: data.subscriptionId,
  }, studioId)
}

async function handleSubscriptionCancelled(event: DodoEvent, supabase: ReturnType<typeof createServiceRoleClient>) {
  const data = event.data as {
    subscriptionId?: string
    metadata?: { studioId?: string }
  }

  const studioId = data.metadata?.studioId
  if (!studioId) return

  const { error } = await supabase
    .from('subscriptions')
    .update({
      status: 'canceled',
      updated_at: new Date().toISOString(),
    })
    .eq('studio_id', studioId)

  if (error) {
    logger.error({ err: error, studioId }, 'dodo webhook: failed to cancel subscription')
    throw error
  }

  await logAuditAction(null, 'subscription.cancelled', { type: 'studio', id: studioId }, null, studioId)
}

function resolvePlanTier(planId: string): 'solo' | 'studio' | 'pro' | 'enterprise' {
  const soloIds = [
    process.env.DODO_PRODUCT_SOLO_MONTHLY,
    process.env.DODO_PRODUCT_SOLO_ANNUAL,
  ]
  const studioIds = [
    process.env.DODO_PRODUCT_STUDIO_MONTHLY,
    process.env.DODO_PRODUCT_STUDIO_ANNUAL,
  ]
  const proIds = [
    process.env.DODO_PRODUCT_PRO_MONTHLY,
    process.env.DODO_PRODUCT_PRO_ANNUAL,
  ]
  const enterpriseIds = [
    process.env.DODO_PRODUCT_ENTERPRISE_MONTHLY,
    process.env.DODO_PRODUCT_ENTERPRISE_ANNUAL,
  ]

  if (soloIds.includes(planId)) return 'solo'
  if (studioIds.includes(planId)) return 'studio'
  if (proIds.includes(planId)) return 'pro'
  if (enterpriseIds.includes(planId)) return 'enterprise'

  logger.warn({ planId }, 'dodo webhook: unknown planId, defaulting to solo')
  return 'solo'
}

export async function POST(req: NextRequest) {
  const webhookKey = process.env.DODO_PAYMENTS_WEBHOOK_KEY
  if (!webhookKey) {
    logger.error('DODO_PAYMENTS_WEBHOOK_KEY is not configured')
    return NextResponse.json({ error: 'webhook not configured' }, { status: 500 })
  }

  // Read raw body once — cannot be re-read after this
  const rawBody = await req.text()
  const signature = req.headers.get('x-dodo-signature')

  // Step 1: Verify HMAC signature with constant-time comparison
  const isValid = await verifySignature(rawBody, signature, webhookKey)
  if (!isValid) {
    logger.warn({ signature: signature?.slice(0, 8) }, 'dodo webhook: invalid signature')
    return NextResponse.json({ error: 'invalid signature' }, { status: 401 })
  }

  // Step 2: Zod parse — reject malformed payloads before any DB write
  let body: unknown
  try {
    body = JSON.parse(rawBody)
  } catch {
    return NextResponse.json({ error: 'invalid json' }, { status: 400 })
  }

  const parsed = DodoEventSchema.safeParse(body)
  if (!parsed.success) {
    logger.warn({ errors: parsed.error.format() }, 'dodo webhook: schema validation failed')
    return NextResponse.json({ error: 'invalid payload shape' }, { status: 400 })
  }

  const event = parsed.data
  const supabase = createServiceRoleClient()

  // Step 3: Idempotency check — deduplicate by webhookId
  const { data: existing } = await supabase
    .from('webhook_events')
    .select('id, processed_at')
    .eq('source', 'dodo')
    .eq('event_id', event.webhookId)
    .maybeSingle()

  if (existing?.processed_at) {
    logger.info({ eventId: event.webhookId }, 'dodo webhook: duplicate event, skipping')
    return NextResponse.json({ received: true, duplicate: true }, { status: 200 })
  }

  // Step 4: Record the event before processing (idempotency row)
  await supabase.from('webhook_events').upsert(
    {
      source: 'dodo',
      event_id: event.webhookId,
      payload: body as Parameters<typeof supabase.from>[0] extends string ? never : typeof body,
      processed_at: null,
      created_at: new Date().toISOString(),
    },
    { onConflict: 'event_id,source' }
  )

  // Step 5: Process event
  try {
    switch (event.eventType) {
      case 'subscription.active':
        await handleSubscriptionActive(event, supabase)
        break
      case 'subscription.cancelled':
        await handleSubscriptionCancelled(event, supabase)
        break
      case 'subscription.renewed':
        await handleSubscriptionActive(event, supabase)
        break
      case 'payment.succeeded':
        logger.info({ eventId: event.webhookId }, 'dodo webhook: payment.succeeded — no-op in Sprint 0')
        break
      case 'payment.failed':
        logger.warn({ eventId: event.webhookId }, 'dodo webhook: payment.failed — dunning in Sprint 4')
        break
      case 'payment.refunded':
        logger.info({ eventId: event.webhookId }, 'dodo webhook: payment.refunded — handled in Sprint 4')
        break
      default:
        logger.info({ eventType: event.eventType }, 'dodo webhook: unhandled event type')
    }

    // Step 6: Mark event as processed
    await supabase
      .from('webhook_events')
      .update({ processed_at: new Date().toISOString() })
      .eq('source', 'dodo')
      .eq('event_id', event.webhookId)

    return NextResponse.json({ received: true }, { status: 200 })
  } catch (err) {
    // Record the error on the webhook_events row for debugging
    await supabase
      .from('webhook_events')
      .update({
        error: err instanceof Error ? err.message : String(err),
      })
      .eq('source', 'dodo')
      .eq('event_id', event.webhookId)

    logger.error({ err, eventId: event.webhookId }, 'dodo webhook: processing failed')
    return NextResponse.json({ error: 'processing failed' }, { status: 500 })
  }
}

