/**
 * Next.js 16 instrumentation — Sentry server-side initialization.
 *
 * This file is auto-loaded by Next.js before starting the server.
 * Split by runtime to load the correct Sentry config.
 */
export async function register() {
  if (process.env.NEXT_RUNTIME === 'nodejs') {
    await import('./sentry.server.config')
  }

  if (process.env.NEXT_RUNTIME === 'edge') {
    await import('./sentry.edge.config')
  }
}

import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NEXT_PUBLIC_APP_ENV ?? 'development',
    service: 'inkos-web',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',
    ],
    censor: '[REDACTED]',
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  ...(process.env.NODE_ENV === 'development' && {
    transport: {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'HH:MM:ss',
        ignore: 'pid,hostname',
      },
    },
  }),
})

/**
 * Create a child logger with request-scoped context.
 */
export function requestLogger(requestId: string) {
  return logger.child({ requestId })
}

/**
 * Server-side feature gating.
 *
 * Returns whether a studio on a given plan tier has access to a feature.
 * For API routes: call requireFeature() to return a 403 response automatically.
 */

export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

const PLAN_ORDER: Record<PlanTier, number> = {
  solo: 0,
  studio: 1,
  pro: 2,
  enterprise: 3,
}

/** Minimum plan required for each feature key */
const FEATURE_MIN_PLAN: Record<string, PlanTier> = {
  inventory: 'studio',
  commissions: 'studio',
  payroll: 'pro',
  ai_design: 'pro',
  guest_artists: 'pro',
  eu_reach: 'pro',
  multi_location: 'pro',
  white_label: 'enterprise',
  api_access: 'enterprise',
}

/**
 * Returns true if the given plan includes the feature.
 */
export function hasFeature(plan: PlanTier, feature: string): boolean {
  const minPlan = FEATURE_MIN_PLAN[feature]
  if (!minPlan) return true // unknown feature = available everywhere
  return PLAN_ORDER[plan] >= PLAN_ORDER[minPlan]
}

/**
 * Returns the minimum plan required for a feature, or null if always available.
 */
export function requiredPlanFor(feature: string): PlanTier | null {
  return FEATURE_MIN_PLAN[feature] ?? null
}

/**
 * Throws a structured error if the plan doesn't include the feature.
 * Use in API Route Handlers:
 *   const guard = requireFeature(studioplan, 'ai_design')
 *   if (guard) return guard
 */
export function requireFeature(
  plan: PlanTier,
  feature: string,
): Response | null {
  if (hasFeature(plan, feature)) return null
  const required = FEATURE_MIN_PLAN[feature] ?? 'pro'
  return Response.json(
    { error: 'Feature not available on current plan', requiredPlan: required },
    { status: 403 },
  )
}
import type { Json } from './supabase/types'

/**
 * Audit log helper.
 *
 * Writes to the audit_log table via the service-role client (bypasses RLS).
 * Every admin action, billing event, and sensitive data access should be logged here.
 *
 * Failures are logged but never throw — audit failures must not break the main flow.
 */
export async function logAuditAction(
  actorId: string | null,
  action: string,
  target: { type: string; id: string } | null,
  details: Json | null,
  studioId: string | null = null
): Promise<void> {
  try {
    // Lazy import to avoid circular deps and to keep this callable from edge runtimes
    const { createServiceRoleClient } = await import('./supabase/server')
    const supabase = createServiceRoleClient()

    await supabase.from('audit_log').insert({
      actor_id: actorId,
      action,
      target_type: target?.type ?? null,
      target_id: target?.id ?? null,
      studio_id: studioId,
      details,
    })
  } catch (err) {
    // Audit failures must not break the primary operation
    const { logger } = await import('./logger')
    logger.error({ err, action, actorId }, 'audit log write failed')
  }
}

